const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#mobile-nav');
// Three-second carousel. Explicit pause, reduced motion and hidden tabs stop rotation.
const carousel=document.querySelector('[data-carousel]');
if(carousel){
 const slides=[...carousel.querySelectorAll('[data-slide]')],motion=matchMedia('(prefers-reduced-motion: reduce)');
 const pause=carousel.querySelector('[data-slide-pause]'),story=carousel.querySelector('.showcase-story');
 let index=0,timer=null,paused=motion.matches;
 function schedule(){clearInterval(timer);timer=null;if(!paused&&!document.hidden)timer=setInterval(()=>show(index+1),3000);}
 let transition=0;
 function loadSlide(n){const img=slides[n].querySelector('img');if(img?.dataset.src){if(img.dataset.srcset){img.srcset=img.dataset.srcset;delete img.dataset.srcset;}img.loading='eager';img.src=img.dataset.src;delete img.dataset.src;}return img?.decode?img.decode().catch(()=>{}):Promise.resolve();}
 async function show(n){const next=(n+slides.length)%slides.length,request=++transition;await loadSlide(next);if(request!==transition)return;index=next;slides.forEach((s,i)=>{s.classList.toggle('is-active',i===index);s.setAttribute('aria-hidden',String(i!==index));});const current=slides[index];carousel.querySelector('[data-slide-label]').textContent=current.dataset.label;carousel.querySelector('[data-slide-title]').textContent=current.dataset.title;story.href=current.dataset.href;carousel.querySelector('.slide-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`;loadSlide((index+1)%slides.length);}
 setTimeout(()=>loadSlide(1),1200);
 function label(){pause.textContent=paused?'Play':'Pause';pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');}
 carousel.querySelector('[data-slide-next]').addEventListener('click',()=>{show(index+1);schedule();});
 carousel.querySelector('[data-slide-prev]').addEventListener('click',()=>{show(index-1);schedule();});
 pause.addEventListener('click',()=>{paused=!paused;label();schedule();});
 document.addEventListener('visibilitychange',schedule);motion.addEventListener('change',()=>{paused=motion.matches;label();schedule();});
 window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('pageshow',schedule);label();schedule();
}
function closeMenu(){if(!menu)return;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');nav.hidden=true;}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open navigation':'Close navigation');nav.hidden=open;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();document.querySelector('dialog[open]')?.close();}});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));}
const search=document.querySelector('#product-search'),filter=document.querySelector('#category-filter');
function filterProducts(){const term=search.value.trim().toLowerCase(),category=filter.value;let total=0;document.querySelectorAll('.filter-item').forEach(el=>{const show=(!category||el.dataset.category===category)&&term.split(/\s+/).every(w=>el.dataset.search.includes(w));el.hidden=!show;if(show){total++;el.querySelector('.reveal')?.classList.add('visible');}});document.querySelector('#result-count').textContent=`${total} product ${total===1?'type':'types'}`;document.querySelector('#no-results').hidden=total!==0;}
search?.addEventListener('input',filterProducts);filter?.addEventListener('change',filterProducts);
let currentView=0;const viewNames=['Overall view','Alternate angle','Detail view','In a space'];
function setView(n){currentView=(n+4)%4;document.querySelectorAll('.gallery-main .product-photo,.dialog-image .product-photo').forEach(el=>{el.classList.remove('view-0','view-1','view-2','view-3');el.classList.add(`view-${currentView}`);el.setAttribute('aria-label',`${document.querySelector('h1').textContent} — ${viewNames[currentView]}`);});document.querySelectorAll('[data-view]').forEach(el=>{const selected=Number(el.dataset.view)===currentView;el.classList.toggle('active',selected);el.setAttribute('aria-pressed',String(selected));});const label=document.querySelector('#dialog-view-label');if(label)label.textContent=`${viewNames[currentView]} · ${currentView+1} / 4`;}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(Number(b.dataset.view))));
const dialog=document.querySelector('#image-dialog');document.querySelector('[data-zoom]')?.addEventListener('click',()=>dialog.showModal());document.querySelector('.dialog-close')?.addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelectorAll('[data-gallery-step]').forEach(b=>b.addEventListener('click',()=>setView(currentView+Number(b.dataset.galleryStep))));
dialog?.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();setView(currentView+1);}if(e.key==='ArrowLeft'){e.preventDefault();setView(currentView-1);}});
const qty=document.querySelector('#quantity'),enquire=document.querySelector('#enquire-product');let finish='Walnut & charcoal';
function updateEnquiry(){if(!enquire)return;const n=Math.max(1,Math.min(9999,parseInt(qty.value)||1));qty.value=n;const params=new URLSearchParams({product:enquire.dataset.product,category:enquire.dataset.category,reference:enquire.dataset.code,quantity:String(n),finish});enquire.href='/contact/?'+params.toString();}
document.querySelectorAll('[data-finish]').forEach(b=>b.addEventListener('click',()=>{finish=b.dataset.finish;document.querySelector('#finish-name').textContent=finish;document.querySelectorAll('[data-finish]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});updateEnquiry();}));
document.querySelectorAll('[data-qty]').forEach(b=>b.addEventListener('click',()=>{qty.value=(parseInt(qty.value)||1)+Number(b.dataset.qty);updateEnquiry();}));qty?.addEventListener('change',updateEnquiry);updateEnquiry();
const form=document.querySelector('#enquiry-form');
if(form){const params=new URLSearchParams(location.search);const product=params.get('product'),category=params.get('category'),service=params.get('service');if(product||service)document.querySelector('#enquiry-subject').value=[product,category].filter(Boolean).join(' — ')||service;document.querySelector('#enquiry-quantity').value=Math.max(1,Math.min(999999,Number(params.get('quantity'))||1));if(product)document.querySelector('#enquiry-message').value=`I would like to discuss ${product}.\n${params.get('reference')?'Product reference: '+params.get('reference')+'\n':''}${params.get('finish')?'Preferred finish: '+params.get('finish')+'\n':''}Project requirements: `;
function brief(){const d=new FormData(form);return `ARVIGA ENQUIRY\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nPhone: ${d.get('phone')||'Not supplied'}\nCompany: ${d.get('company')||'Not supplied'}\nProduct / service: ${d.get('subject')}\nQuantity: ${d.get('quantity')}\nLocation: ${d.get('location')||'Not supplied'}\n\n${d.get('message')}\n\nDisplayed prices are examples. Please confirm the final design, specifications, price, delivery and terms.\n`;}
function download(){if(!form.reportValidity())return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([brief()],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='ARVIGA-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your enquiry brief has been downloaded. It has not been sent to ARVIGA.';}
document.querySelector('#download-enquiry')?.addEventListener('click',download);
form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;if(form.dataset.email){location.href=`mailto:${form.dataset.email}?subject=${encodeURIComponent('ARVIGA enquiry: '+new FormData(form).get('subject'))}&body=${encodeURIComponent(brief())}`;document.querySelector('#form-status').textContent='Your email app has been requested. Review and send the message there; nothing has been sent by this website.';}else if(form.dataset.whatsapp){window.open(`https://wa.me/${form.dataset.whatsapp.replace(/\D/g,'')}?text=${encodeURIComponent(brief())}`,'_blank','noopener');document.querySelector('#form-status').textContent='Continue in WhatsApp to review and send your enquiry.';}else download();});}
// Optional agent access to the same visible filtering and enquiry configuration.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
if(search)register({name:'filter_furniture_catalogue',title:'Filter furniture catalogue',description:'Update the visible furniture search and collection filter. Returns matching names and product page paths; does not navigate or send enquiries.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:100},category:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.query!=='string'||input.query.length>100||Object.keys(input).some(k=>!['query','category'].includes(k)))throw new Error('Provide a query of up to 100 characters and an optional category slug.');const cat=input.category??'';if(typeof cat!=='string'||![...filter.options].some(o=>o.value===cat))throw new Error('Unknown collection slug.');search.value=input.query;filter.value=cat;filterProducts();const matches=[...document.querySelectorAll('.filter-item:not([hidden])')].map(el=>({name:el.querySelector('h3').textContent,url:el.querySelector('a').getAttribute('href')}));return {count:matches.length,matches};}});
if(enquire)register({name:'configure_product_enquiry',title:'Configure product enquiry',description:'Set the visible quantity and finish preference for this product. Returns the enquiry link. Does not submit a message, confirm a price, add an order or purchase anything.',inputSchema:{type:'object',properties:{quantity:{type:'integer',minimum:1,maximum:9999},finish:{type:'string',enum:['Walnut & charcoal','Natural oak tone','Charcoal']}},required:['quantity','finish'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['quantity','finish'].includes(k))||!Number.isInteger(input.quantity)||input.quantity<1||input.quantity>9999||!['Walnut & charcoal','Natural oak tone','Charcoal'].includes(input.finish))throw new Error('Choose a quantity from 1 to 9999 and one of the displayed finish preferences.');qty.value=input.quantity;[...document.querySelectorAll('[data-finish]')].find(b=>b.dataset.finish===input.finish).click();updateEnquiry();return {product:enquire.dataset.product,quantity:input.quantity,finish,enquiryUrl:enquire.getAttribute('href'),status:'configured_not_sent'};}});
}
